    this.clearRowError(p.id);
    const sheet = this.session.sheet();
    try {
      const cancelled = await firstValueFrom(
        this.http.post<StatementTaken>('/api/statements/cancel', { sheet, user: this.session.user(), personId: p.id }),
      );
